package httpapi

import (
	"bytes"
	"encoding/json"
	"net/http"
	"strings"
	"sync"
	"sync/atomic"

	"github.com/trypando/pando/internal/core/authz"
	"github.com/trypando/pando/internal/errs"
	"github.com/trypando/pando/internal/reference"
)

// The API's own description (R-261).
//
// chi knows every route's method and pattern and nothing about what any of them
// is for, so the summaries live here, beside the router, and
// `TestEveryRouteIsDocumented` walks the real router and fails when this table
// and that router disagree in either direction. Adding an endpoint without
// describing it fails the build; so does describing one that no longer exists.
// That is the whole mechanism, and it is the reason this file is worth
// maintaining: the reference cannot rot quietly, because rot is a red test.
//
// The verb on each row is the authorization verb the handler checks (design 06
// §5). Empty means the endpoint asks for nothing beyond being signed in — which
// is an answer somebody needs, not an omission.
var routeDocs = []reference.Route{
	// --- session and account ---------------------------------------------
	{Method: "POST", Path: "/api/v1/sessions", Group: "Session", Title: "Sign in", Summary: "Sign in with a username and password. Sets the session cookie. An account with two-factor authentication also needs `code`, a code from its authenticator app or one of its recovery codes: without it the answer is `AUTH_TWO_FACTOR_REQUIRED`, and the same request is sent again with it (R-405). `two_factor_setup_required` in the answer says the session can do nothing but set up two-factor authentication, which host policy `require_local_two_factor` asks of every local account. Refused when host policy has `disable_password_sign_in` on.", Public: true},
	{Method: "GET", Path: "/api/v1/auth/options", Group: "Session", Title: "List sign-in options", Summary: "How people can sign in here: whether password sign-in is on, and the identity providers that are (`id`, `name`, `kind`). Public.", Public: true},
	{Method: "GET", Path: "/api/v1/auth/providers/{providerID}/start", Group: "Session", Title: "Start provider sign-in", Summary: "Start signing in through an identity provider: a browser navigation, redirected to the provider. `next` is the path to land on afterwards. Works under `/.pando` on an app's own hostname too. Public.", Public: true},
	{Method: "GET", Path: "/api/v1/auth/providers/{providerID}/callback", Group: "Session", Title: "OIDC callback", Summary: "Where an OpenID Connect provider returns the browser: the redirect URI to register with it. Public.", Public: true},
	{Method: "POST", Path: "/api/v1/auth/providers/{providerID}/callback", Group: "Session", Title: "SAML assertion consumer", Summary: "Where a SAML provider posts its response: the Assertion Consumer Service URL to register with it. Public.", Public: true},
	{Method: "GET", Path: "/api/v1/auth/providers/{providerID}/metadata", Group: "Session", Title: "SAML metadata", Summary: "Pando's SAML service provider metadata for this provider. Its URL is also the entity ID. Public.", Public: true},
	{Method: "GET", Path: "/api/v1/auth/complete", Group: "Session", Title: "Finish provider sign-in", Summary: "Finish a provider sign-in in the browser that started it, with the one-time `code` the callback issued. Sets the session cookie and redirects to where the sign-in began. Public.", Public: true},
	{Method: "GET", Path: "/api/v1/auth/failures/{flowID}", Group: "Session", Title: "Get a sign-in failure", Summary: "Why a provider sign-in failed (`message`, `remedy`), for the sign-in page. Public.", Public: true},
	{Method: "POST", Path: "/api/v1/cli-sign-ins", Group: "Session", Title: "Approve a CLI sign-in", Summary: "Let the CLI that opened this browser sign in as you (R-406): the console's approval page sends on what `pando login` put in its address — `code_challenge` (base64url SHA-256 of the CLI's verifier), `code_challenge_method` (`S256`), `name` (the token's) and `port`, the loopback port the CLI listens on, with `state`; or `port` 0 when the code will be pasted. Answers with a one-time `code`, valid 5 minutes, and `redirect_url`, the CLI's `http://127.0.0.1:{port}/callback` address carrying it, empty when pasted. A session only: a token cannot approve."},
	{Method: "POST", Path: "/api/v1/cli-sign-ins/token", Group: "Session", Title: "Collect a CLI sign-in", Summary: "Trade an approved sign-in's `code` and the `code_verifier` behind its challenge for a delegated token acting as whoever approved it, bounded by their live grants (R-058, R-059) and host policy's token lifetime (R-061). Answers with `token`, `secret` (shown once) and `username`. A code is tried once: any attempt spends it, so a wrong verifier ends the sign-in. Public: the verifier is the proof (R-406).", Public: true},
	{Method: "DELETE", Path: "/api/v1/sessions", Group: "Session", Title: "Sign out", Summary: "Sign out, ending this session."},
	{Method: "GET", Path: "/api/v1/setup", Group: "Session", Title: "Get setup status", Summary: "Whether this installation is waiting for its first administrator (`needed`). Public.", Public: true},
	{Method: "POST", Path: "/api/v1/setup", Group: "Session", Title: "Set up the installation", Summary: "Set up a new installation: the first account (`username`, `display_name`, `password`), made an administrator, and signed in. Public, but needs the one-time `setup_token` Pando printed to its log at startup (`pando admin setup-token` makes a new one), and refused once any account exists (R-046).", Public: true},
	{Method: "GET", Path: "/api/v1/me", Group: "Session", Title: "Get the current caller", Summary: "Who the caller is, and the install-level verbs they hold. On a local account, `two_factor` says whether two-factor authentication is on (`enabled`), whether host policy requires it (`required`) and so must be set up before anything else (`setup_required`), whether to ask its holder to set it up (`offer`, true once), how many recovery codes are left, and whether changing it needs the current password (`password_required`, false within 10 minutes of signing in) (R-405)."},
	{Method: "POST", Path: "/api/v1/me/password", Group: "Session", Title: "Change your password", Summary: "Change your own password. Yours only, whatever verbs you hold."},
	{Method: "POST", Path: "/api/v1/me/two-factor/totp", Group: "Session", Title: "Start setting up an authenticator", Summary: "Make a new authenticator app key for your own local account: `secret` to type in, `uri` (an `otpauth://` key URI) and `qr_svg`, a QR code of it. It is not in use until confirmed with a code from it, and an authenticator already in use stays in use until then, so this is also how one is replaced. Needs `current_password` unless you signed in within 10 minutes (R-405)."},
	{Method: "POST", Path: "/api/v1/me/two-factor/totp/confirm", Group: "Session", Title: "Confirm an authenticator", Summary: "Put the authenticator from POST /me/two-factor/totp in use, given a `code` from it. Answers with `recovery_codes`, ten codes that each sign in once in place of a code. They are shown this once (R-405)."},
	{Method: "POST", Path: "/api/v1/me/two-factor/recovery-codes", Group: "Session", Title: "Make new recovery codes", Summary: "Replace your recovery codes with ten new ones, shown this once; the old ones stop working. Needs `current_password` unless you signed in within 10 minutes (R-405)."},
	{Method: "POST", Path: "/api/v1/me/two-factor/skip", Group: "Session", Title: "Decline two-factor setup", Summary: "Say not now when asked to set up two-factor authentication, so you are not asked again. Refused where host policy requires it (R-405)."},
	{Method: "DELETE", Path: "/api/v1/me/two-factor", Group: "Session", Title: "Turn off two-factor authentication", Summary: "Turn off two-factor authentication on your own local account, removing its authenticator and recovery codes. Refused with `POLICY_TWO_FACTOR_REQUIRED` where host policy requires it. Needs `current_password` unless you signed in within 10 minutes (R-405)."},
	{Method: "GET", Path: "/api/v1/me/apps", Group: "Session", Title: "List your apps", Summary: "The apps you can open, which is a different list from the apps you can administer (R-070, R-071). `favorite` marks the ones you have pinned, `section_id` the section you filed each under, and `sections` lists your sections. `can_manage` marks the ones you can also administer — those GET /apps lists for you. Favorites first, then apps filed in a section, then the rest, each by name, a page at a time: `limit` (default 100, at most 500), `cursor` (the previous page's `next_cursor`, empty after the last page) and `q` to match the name or slug."},
	{Method: "PUT", Path: "/api/v1/me/favorites/{appID}", Group: "Session", Title: "Add a favorite", Summary: "Mark an app you can open as a favorite, pinning it to the top of your launcher. Yours only; it grants nothing (R-341)."},
	{Method: "DELETE", Path: "/api/v1/me/favorites/{appID}", Group: "Session", Title: "Remove a favorite", Summary: "Unpin an app from your favorites."},
	{Method: "POST", Path: "/api/v1/me/sections", Group: "Session", Title: "Create a section", Summary: "Make a section in your launcher: a named, collapsible grouping of apps. Yours only; it grants nothing (R-342)."},
	{Method: "PATCH", Path: "/api/v1/me/sections/{sectionID}", Group: "Session", Title: "Rename a section", Summary: "Rename one of your sections."},
	{Method: "DELETE", Path: "/api/v1/me/sections/{sectionID}", Group: "Session", Title: "Delete a section", Summary: "Delete one of your sections. Its apps go back to Your apps."},
	{Method: "PUT", Path: "/api/v1/me/sections/{sectionID}/apps/{appID}", Group: "Session", Title: "Add app to a section", Summary: "File an app you can open into one of your sections, moving it out of any other."},
	{Method: "DELETE", Path: "/api/v1/me/sections/{sectionID}/apps/{appID}", Group: "Session", Title: "Remove app from a section", Summary: "Take an app out of a section, back to Your apps."},

	// --- tokens -----------------------------------------------------------
	{Method: "GET", Path: "/api/v1/tokens", Group: "Tokens", Title: "List your tokens", Summary: "Your own tokens. Never anyone else's."},
	{Method: "POST", Path: "/api/v1/tokens", Group: "Tokens", Title: "Create a delegated token", Summary: "Mint a delegated token. It acts as you, is bounded by your live grants, and dies with your account (R-058, R-059). The secret is shown once."},
	{Method: "GET", Path: "/api/v1/tokens/service", Group: "Tokens", Title: "List service tokens", Summary: "The installation's service tokens.", Verb: string(authz.InstallTokensManage)},
	{Method: "POST", Path: "/api/v1/tokens/service", Group: "Tokens", Title: "Create a service token", Summary: "Mint a service token: its own principal, holding only what is shared with it, outliving whoever created it (R-060). The secret is shown once.", Verb: string(authz.InstallTokensManage)},
	{Method: "DELETE", Path: "/api/v1/tokens/{tokenID}", Group: "Tokens", Title: "Revoke a token", Summary: "Revoke a token. Yours; a service token with install.tokens.manage; anyone else's with install.users.manage."},

	// --- apps -------------------------------------------------------------
	{Method: "GET", Path: "/api/v1/apps", Group: "Apps", Title: "List apps", Summary: "The apps you can administer. Each carries `detection` — its status, and its stage while running — once it has been through detection. Newest first, a page at a time: `limit` (default 100, at most 500), `cursor` (the previous page's `next_cursor`, which is empty after the last page), `q` to match the name or slug, and `id`, repeatable, to read only those apps. `total` counts the matches exactly up to 10,000; past that it is 10,000 and `total_is_lower_bound` is true (O-53)."},
	{Method: "POST", Path: "/api/v1/apps", Group: "Apps", Title: "Create an app", Summary: "Create an app. `source` is `{type: git, url, ref, connection}` for a repository — `connection` optional, the source connection to read a private one with; left out, the one covering the address most closely is used — `{type: image, image, credential}` for an image that is already built (`credential` optional, for a private one: see PUT /registry-credential), or `{type: upload}` for files sent next with POST /source. A repository address is https, http or ssh (`git@host:path` included), with no username, password or token in it — a credential belongs in a source connection. Checked against the source allowlist before anything is fetched (R-092), then the repository is checked to be readable, so a private one no connection can read is refused with `VALID_SOURCE_UNREADABLE` saying why (R-091). Returns immediately in draft while detection runs; follow it with GET /detection and `wait`.", Verb: string(authz.AppCreate)},
	{Method: "GET", Path: "/api/v1/apps/{appID}", Group: "Apps", Title: "Get an app", Summary: "One app: name, source, state and pinned spec; `detection` — its status, and its stage while running — once it has been through detection; and `last_backup`, its last daily backup attempt.", Verb: string(authz.AppView)},
	{Method: "PATCH", Path: "/api/v1/apps/{appID}", Group: "Apps", Title: "Update an app", Summary: "Rename an app.", Verb: string(authz.AppSpecEdit)},
	{Method: "DELETE", Path: "/api/v1/apps/{appID}", Group: "Apps", Title: "Delete an app", Summary: "Delete an app. With storage, `backup=true` keeps a final copy and `force=true` discards it; without either, the request is refused so the decision is taken rather than assumed (R-204, R-205). When host policy has `require_backup_before_destroy`, `force=true` is refused for an app with storage (R-284).", Verb: string(authz.AppDelete)},
	{Method: "GET", Path: "/api/v1/apps/{appID}/icon", Group: "Apps", Title: "Get an app's image", Summary: "The image on the app's launcher tile. Anyone who can open the app can load it; `icon_updated_at` on the app says whether there is one and when it changed (R-340)."},
	{Method: "PUT", Path: "/api/v1/apps/{appID}/icon", Group: "Apps", Title: "Set an app's image", Summary: "Set the app's tile image. The body is the image itself — PNG, JPEG, WebP or GIF, at most 256 KB. SVG is refused (R-340).", Verb: string(authz.AppSpecEdit)},
	{Method: "DELETE", Path: "/api/v1/apps/{appID}/icon", Group: "Apps", Title: "Remove an app's image", Summary: "Remove the app's tile image, so the tile goes back to the map generated for it.", Verb: string(authz.AppSpecEdit)},
	{Method: "GET", Path: "/api/v1/apps/{appID}/usage", Group: "Apps", Title: "Get an app's usage", Summary: "What each part of the app is using now — CPU in thousandths of a core, memory and disk in bytes, and each mounted volume's size — beside its limits (0 is none; `host_cpu_millis` and `host_memory_bytes` say what none means). A reading, not a history (R-245, R-016). `supported: false` when the runtime cannot report it.", Verb: string(authz.AppView)},
	{Method: "GET", Path: "/api/v1/apps/{appID}/status", Group: "Apps", Title: "Get an app's status", Summary: "What the app is doing now: its state, and each part separately — running, restarting and how often, health, exit code — so a single crash-looping part is visible rather than averaged into one word. `auto_deploy_paused` is true when the spec asks for auto-deploy and approval now stops it (R-158).", Verb: string(authz.AppView)},
	{Method: "POST", Path: "/api/v1/apps/{appID}/start", Group: "Apps", Title: "Start an app", Summary: "Set the app's desired state to running. The reconciler converges to it, so it survives a restart.", Verb: string(authz.AppRestart)},
	{Method: "POST", Path: "/api/v1/apps/{appID}/stop", Group: "Apps", Title: "Stop an app", Summary: "Set the app's desired state to stopped.", Verb: string(authz.AppRestart)},
	{Method: "POST", Path: "/api/v1/apps/{appID}/restart", Group: "Apps", Title: "Restart an app", Summary: "Restart the running workloads without changing anything.", Verb: string(authz.AppRestart)},
	{Method: "GET", Path: "/api/v1/apps/{appID}/idle", Group: "Apps", Title: "Get idle settings", Summary: "Whether Pando stops or deletes this app when nobody uses it (R-393 – R-397): its own `stop_days` and `delete_days` (null is the installation's, 0 is off), the installation's, the ones in force, `last_activity_at`, and `stops_at` and `deletes_at` if nothing happens before then. `stopped_for_idle` says Pando stopped it.", Verb: string(authz.AppView)},
	{Method: "PUT", Path: "/api/v1/apps/{appID}/idle", Group: "Apps", Title: "Set idle settings", Summary: "Set this app's own `stop_days` and `delete_days`: a number of days, 0 to turn it off, or null for the installation's. Deleting has to come later than stopping. App settings, not spec: no revision is written and nothing is deployed (R-397). Withdraws any notice already given.", Verb: string(authz.AppSpecEdit)},
	{Method: "GET", Path: "/api/v1/apps/{appID}/logs", Group: "Apps", Title: "Read app logs", Summary: "The app's own output, from the runtime, as plain text. `tail` sets how many of the most recent lines (default 200, at most 5000; a larger number is read as 5000); `workload` picks which part of the app, defaulting to the primary one. `follow=true` keeps the response open and adds each new line as it is printed, from the same shared stream as /logs/stream, starting from the recent lines that stream holds rather than from `tail`.", Verb: string(authz.AppLogsRead)},
	{Method: "GET", Path: "/api/v1/apps/{appID}/logs/stream", Group: "Apps", Title: "Stream app logs", Summary: "The app's own output live, as server-sent events (O-51). `workload` picks the part, defaulting to the primary one. Opens with `event: reset` and up to the last 1000 lines, then sends each new line as a `data:` event; `event: notice` reports the runtime's stream ending (a restart) and being reconnected. Access is checked again every two minutes: the stream ends with `event: revoked` when it no longer holds, and a client must not reconnect after it; `event: lagged` means the client fell too far behind and may reconnect. Every viewer of a part on one Pando server shares one stream from the runtime.", Verb: string(authz.AppLogsRead)},
	{Method: "GET", Path: "/api/v1/apps/{appID}/exec", Group: "Apps", Title: "Open a terminal", Summary: "A terminal in the running app, over a websocket. Refused when host policy has turned exec off, including for the owner (R-085).", Verb: string(authz.AppExec)},

	// --- detection --------------------------------------------------------
	{Method: "GET", Path: "/api/v1/apps/{appID}/detection", Group: "Detection", Title: "Get detection", Summary: "What Pando worked out about the repository: the winning bid, its evidence, the runners-up and any outstanding questions. While `status` is `running`, `stage` is one of fetching, detecting, building, trying, scanning or screening, `running` lists every step under way (the scan runs beside the build and beside the trial), and `elapsed_seconds` says how long it has been going. A failed build carries its log in `detection.error.details.build_log`. `wait` (seconds, up to 60) holds the answer until detection reaches a new stage or finishes.", Verb: string(authz.AppView)},
	{Method: "POST", Path: "/api/v1/apps/{appID}/detection/rerun", Group: "Detection", Title: "Run detection again", Summary: "Run detection again, against the current commit.", Verb: string(authz.AppSpecEdit)},
	{Method: "GET", Path: "/api/v1/apps/{appID}/detection/diff", Group: "Detection", Title: "Preview detection changes", Summary: "What accepting the proposal would change about the running app.", Verb: string(authz.AppView)},
	{Method: "POST", Path: "/api/v1/apps/{appID}/detection/answers", Group: "Detection", Title: "Answer detection questions", Summary: "Answer detection's questions. Each answer is a fact detection could not find, not a preference. An answer that changes what is built — a build argument — has Pando build and scan the image again, so the plan shows the score of what will run; detection reads as `running` until it has. Answering `deployable_project` runs detection again in that project.", Verb: string(authz.AppSpecEdit)},
	{Method: "POST", Path: "/api/v1/apps/{appID}/detection/revise", Group: "Detection", Title: "Revise the detection plan", Summary: "Tell the AI adapter what is wrong with the plan (`message`). It checks the repository, changes what it can show, replies, and records the exchange on the proposal. Needs an AI adapter.", Verb: string(authz.AppSpecEdit)},
	{Method: "POST", Path: "/api/v1/apps/{appID}/detection/accept", Group: "Detection", Title: "Accept the detection proposal", Summary: "Accept the proposal, writing a spec revision and pinning it. `values` sets variables in the same step — `{key, value, secret?, workload?}` each; a secret goes to the secrets adapter and needs app.secrets.write. Accepting over a configured app needs `confirm`. Refused while detection is running, including while it builds and scans after an answer.", Verb: string(authz.AppSpecEdit)},
	{Method: "POST", Path: "/api/v1/apps/{appID}/source", Group: "Detection", Title: "Upload an app's source", Summary: "Send an app's files as its source: a gzipped tar of the app's directory (Content-Type `application/gzip`, at most 256 MB), paths relative to its root. A single index.html is enough for a static site. Replaces any files sent before; follow it with POST /detection/rerun. Refused under a source allowlist that does not include `upload` (R-092).", Verb: string(authz.AppSpecEdit)},

	// --- specs ------------------------------------------------------------
	{Method: "GET", Path: "/api/v1/apps/{appID}/specs", Group: "Configuration", Title: "List spec revisions", Summary: "Every spec revision, and which one is pinned. Revisions are append-only (R-152).", Verb: string(authz.AppView)},
	{Method: "POST", Path: "/api/v1/apps/{appID}/specs", Group: "Configuration", Title: "Create a spec revision", Summary: "Write a new spec revision. It does not deploy and does not become pinned. A routing mode other than its adapter's default, where the app did not already have one, also needs app.routing.override (R-163). A change to `resources`, or to a workload's own `resources`, also needs app.resources.override, unless it puts back the installation's defaults (R-241). A change to `egress` needs app.egress.tighten or app.egress.loosen; one that newly loosens the installation's egress rules needs app.egress.loosen where policy gates loosening by verb, is refused with PLAN_EGRESS_LOOSENING_FORBIDDEN where policy forbids it, and makes the next deploy need approval where policy says so (R-183, R-184). Turning on automatic deploys while the app's deploys need approval is refused (R-158). With `?dry_run=true` nothing is written: the same checks run and refuse with the same errors, and an accepted spec answers 200 with the egress rules it would run with, what it newly loosens, and whether deploying it would need approval and why.", Verb: string(authz.AppSpecEdit)},
	{Method: "GET", Path: "/api/v1/apps/{appID}/routing", Group: "Configuration", Title: "Get routing", Summary: "Where the app is reached, where it will be after the next deploy when a change is saved (`next_address`), and the routing adapters it could move to, with the modes each serves and defaults to, and the `domains` a hostname can be in under each, such as every zone of a Cloudflare adapter.", Verb: string(authz.AppView)},
	{Method: "PUT", Path: "/api/v1/apps/{appID}/routing", Group: "Configuration", Title: "Change routing", Summary: "Change where a configured app is reached: `adapter_ref`, `mode`, and `hostname` or `path_prefix` (such as `/team/notes`), each defaulting to the adapter's own. `domain` picks one of the adapter's `domains`: alone it makes `<slug>.<domain>`, and with a single-label `hostname` such as `docs` it makes `docs.<domain>`; a hostname outside every domain is refused. Writes a revision the next deploy ships. A change needs `confirm: true`, since the old address stops working; a mode the adapter does not default to also needs app.routing.override (R-163). An address another app holds, or a path inside or around another app's, is refused with STATE_ADDRESS_TAKEN.", Verb: string(authz.AppSpecEdit)},
	{Method: "GET", Path: "/api/v1/apps/{appID}/auto-deploy", Group: "Configuration", Title: "Get auto-deploy settings", Summary: "The app's automatic deploy settings (R-141): `settings` on the newest revision and `deployed` on the pinned one, with `pending` when they differ; `paused` when approval now stops it (R-158); `last_check`, what the last check found (`found_ref`, `found_commit`), the last commit it tried (`attempted_commit`, each commit is tried once) and why it went nowhere (`error`); and `webhook_url` with `webhook_secret_set`.", Verb: string(authz.AppView)},
	{Method: "PUT", Path: "/api/v1/apps/{appID}/auto-deploy", Group: "Configuration", Title: "Change auto-deploy settings", Summary: "Change the automatic deploy settings: `enabled`, `trigger` (`branch_updated`, the default, or `release_tagged`), `branch` (empty follows the branch the app was deployed from) and `tag_pattern` (a glob such as `release-*`; empty counts tags like `v1.2.3` as releases). Writes a revision the next deploy ships; 200 with `changed: false` when nothing changes. Refused while the app's deploys need approval (R-158).", Verb: string(authz.AppSpecEdit)},
	{Method: "POST", Path: "/api/v1/apps/{appID}/auto-deploy/webhook-secret", Group: "Configuration", Title: "Create a webhook secret", Summary: "Make the app a new webhook secret, replacing any it had, and return it with `webhook_url`. The only time the secret is shown. Paste both into the git host's webhook settings (R-142).", Verb: string(authz.AppSpecEdit)},
	{Method: "DELETE", Path: "/api/v1/apps/{appID}/auto-deploy/webhook-secret", Group: "Configuration", Title: "Remove the webhook secret", Summary: "Remove the app's webhook secret, which turns its webhook off. Polling carries on.", Verb: string(authz.AppSpecEdit)},
	{Method: "POST", Path: "/api/v1/apps/{appID}/auto-deploy/webhook", Group: "Configuration", Title: "Git host webhook", Summary: "Where a git host sends push and release events (R-142): GitHub's format, `X-GitHub-Event` and `X-Hub-Signature-256` signed with the app's webhook secret. A verified delivery about what the app watches starts a check (202); one about something else is ignored (200). The check reads the repository itself, so nothing in the payload decides what deploys. Public: the signature is the credential.", Public: true},
	{Method: "GET", Path: "/api/v1/apps/{appID}/specs/{rev}", Group: "Configuration", Title: "Get a spec revision", Summary: "One revision, in full.", Verb: string(authz.AppView)},
	{Method: "POST", Path: "/api/v1/apps/{appID}/specs/{rev}/pin", Group: "Configuration", Title: "Pin a spec revision", Summary: "Pin a revision: what the reconciler converges to, and what the next deploy ships. On an app that has been deployed it changes what runs, so it also needs `app.deploy`, passes the same gates as a deploy, and is refused for a revision whose deploy needs approval: deploy that revision instead (R-154).", Verb: string(authz.AppSpecEdit)},
	{Method: "GET", Path: "/api/v1/apps/{appID}/specs/{a}/diff/{b}", Group: "Configuration", Title: "Compare two spec revisions", Summary: "The classified difference between two revisions — what a deploy of it would restart, rebuild or leave alone.", Verb: string(authz.AppView)},
	{Method: "GET", Path: "/api/v1/apps/{appID}/export", Group: "Configuration", Title: "Export an app's configuration", Summary: "The app's configuration as a document, with every secret redacted (R-194).", Verb: string(authz.AppView)},
	{Method: "POST", Path: "/api/v1/apps/{appID}/plan", Group: "Configuration", Title: "Plan a deploy", Summary: "What a deploy of the pinned spec would do, and every reason it would refuse — before anything is created. Carries the egress rules the app would run with, merged, with where each part came from and what every loosening needs (`egress`, R-188), `notes`, and whether the deploy would need approval and why (`approval`, R-154).", Verb: string(authz.AppView)},
	{Method: "GET", Path: "/api/v1/apps/{appID}/egress", Group: "Configuration", Title: "Get egress rules", Summary: "The installation's egress rules (`install`: mode, list, private-address blocking, and what loosening them needs), the rules the pinned spec runs with, merged, with every loosening and what it needs (`effective`), the pinned spec's own egress settings (`spec`), and which revision those are (`revision`). `?revision=N`, or `?revision=latest` for the newest, reads that revision instead — what a saved change not yet deployed would run with. Change them by writing a spec (R-182, R-188).", Verb: string(authz.AppView)},
	{Method: "GET", Path: "/api/v1/apps/{appID}/slots", Group: "Configuration", Title: "List slots", Summary: "The things the app says it needs, and what fills each one (R-130).", Verb: string(authz.AppView)},
	{Method: "PUT", Path: "/api/v1/apps/{appID}/slots/{key}", Group: "Configuration", Title: "Fill a slot", Summary: "Fill a slot: provision one, bind to something already running, or set a value. Takes effect at the next deploy.", Verb: string(authz.AppSpecEdit)},
	{Method: "GET", Path: "/api/v1/apps/{appID}/volumes", Group: "Storage", Title: "List volumes", Summary: "The storage this app keeps. It outlives the app (R-204).", Verb: string(authz.AppView)},
	{Method: "POST", Path: "/api/v1/apps/{appID}/volumes", Group: "Storage", Title: "Create a volume", Summary: "Declare a path the app keeps between deploys. Anything written outside one is discarded at the next deploy (R-201).", Verb: string(authz.AppSpecEdit)},
	{Method: "POST", Path: "/api/v1/apps/{appID}/restore", Group: "Storage", Title: "Restore an app's storage", Summary: "Restore this app's storage from one of its backups.", Verb: string(authz.AppDeploy)},

	// --- deploys ----------------------------------------------------------
	{Method: "GET", Path: "/api/v1/apps/{appID}/deployments", Group: "Deploys", Title: "List deployments", Summary: "Every deploy of this app, newest first. One waiting in the queue for a build slot carries `queue_position`: how many queued deploys are ahead of it, 0 for the next.", Verb: string(authz.AppView)},
	{Method: "POST", Path: "/api/v1/apps/{appID}/deployments", Group: "Deploys", Title: "Deploy an app", Summary: "Deploy. Returns 202 with the deployment; the build runs behind it. `spec_revision` names the revision to ship; without it the pinned one ships, and when a newer revision exists — an edit not yet deployed — the reply carries it as `newer_revision`. When the deploy needs approval (R-154) it comes back `awaiting_approval` instead, the app is left as it is, the people who can approve are told, and any older request for the app still waiting is superseded. Retrying with the same idempotency key replays the first answer rather than deploying twice (R-262).", Verb: string(authz.AppDeploy)},
	{Method: "GET", Path: "/api/v1/apps/{appID}/deployments/{depID}", Group: "Deploys", Title: "Get a deployment", Summary: "One deploy: what it shipped, and how it ended. One that needed approval carries `approvals_required`, `approval_expires_at`, `approval_reasons`, the `approvals` so far and, while it waits, `can_decide`. One waiting in the queue for a build slot carries `queue_position`, how many are ahead of it.", Verb: string(authz.AppView)},
	{Method: "GET", Path: "/api/v1/apps/{appID}/deployments/{depID}/logs", Group: "Deploys", Title: "Stream deployment logs", Summary: "The deploy's output as server-sent events, flushed per line while it runs (R-170). While the deploy waits in the queue, a line saying how many deploys are ahead of it, again each time that changes; then the deploy's own output in the same stream.", Verb: string(authz.AppLogsRead)},
	{Method: "POST", Path: "/api/v1/apps/{appID}/deployments/rollback", Group: "Deploys", Title: "Roll back an app", Summary: "Deploy the last revision that ran successfully, or the revision `to` names. Rolling back to a revision that ran successfully before never needs approval (R-157).", Verb: string(authz.AppDeploy)},
	{Method: "GET", Path: "/api/v1/apps/{appID}/image-update", Group: "Deploys", Title: "Check for a newer image", Summary: "For an app deployed from a published image: whether its tag now names a different build than the pinned revision runs. Returns `image`, `current_digest`, `latest_digest`, `update_available` and the `revision` checked. Writes nothing (R-143a).", Verb: string(authz.AppView)},
	{Method: "POST", Path: "/api/v1/apps/{appID}/image-update", Group: "Deploys", Title: "Upgrade to a newer image", Summary: "Write a revision running `digest`, the `latest_digest` a check returned, and deploy it; also needs app.deploy. Refused when the tag has moved since the check, when nothing is newer, or while a newer revision is saved and not deployed. Answers as POST /deployments does, approval included, and a retry with the same idempotency key replays the first answer (R-143a, R-154, R-262).", Verb: string(authz.AppSpecEdit)},
	{Method: "POST", Path: "/api/v1/apps/{appID}/deployments/{depID}/approve", Group: "Deploys", Title: "Approve a deployment", Summary: "Approve a deploy that is waiting for approval, with an optional `comment`. Takes `install.deploys.approve`, or `app.deploy.approve` on this app; either may approve its holder's own request (R-155). The last approval it needs plans it again and starts it: 200 with the deployment, `pending` once started and still `awaiting_approval` while it needs more. Refused while another deploy of the app is running; the request keeps waiting.", Verb: string(authz.AppView)},
	{Method: "POST", Path: "/api/v1/apps/{appID}/deployments/{depID}/reject", Group: "Deploys", Title: "Reject a deployment", Summary: "Reject a deploy that is waiting for approval, with an optional `comment`. One rejection ends the request (R-156). The same permissions as approving.", Verb: string(authz.AppView)},
	// --- notification adapters (R-374) ---------------------------------------
	{Method: "GET", Path: "/api/v1/notify", Group: "Installation", Title: "List notification adapters", Summary: "The notification adapters, each with its `capabilities` — `audience`, whether it is `authorized` (connected), whether it can be connected in the browser (`web_authorization`) or by hand (`manual_authorization`), whether a subscription to it names a channel (`channels`), and `manage_url`, the provider's page for what connecting created — and `problem`, why one cannot send. Built from their settings as they are now, so one added or connected needs no restart.", Verb: string(authz.InstallView)},
	{Method: "POST", Path: "/api/v1/notify/{adapterID}/authorize", Group: "Installation", Title: "Connect a notification adapter", Summary: "Connect an adapter to its provider; for Slack, create Pando's Slack app and install it. `mode` `web` (the default) takes `token`, a Slack configuration token used once and never stored, creates the app, gives it Pando's icon, and returns `authorize_url`, Slack's approval screen, which comes back to GET /api/v1/notify/callback; Slack returns only to an https address. `mode` `manual` without `token` returns `authorize_url`, Slack's create-app page with Pando's app filled in; with `token`, the bot token the app shows once installed, it checks and stores it and answers `status` `authorized`.", Verb: string(authz.InstallAdaptersManage)},
	{Method: "GET", Path: "/api/v1/notify/callback", Group: "Installation", Title: "Notification adapter callback", Summary: "Where Slack returns the browser after approving Pando's app. Stores the bot token and redirects to the console's Adapters screen with `authorized` or `error`.", Verb: string(authz.InstallAdaptersManage)},
	{Method: "GET", Path: "/api/v1/notify/{adapterID}/channels", Group: "Events", Title: "List an adapter's channels", Summary: "The channels a subscription to the adapter can post to — for Slack, the workspace's public channels and the private ones Pando was invited to — each `id`, `name` and `private`. `q` narrows by name. Only for an adapter whose capabilities say `channels`."},

	// --- events and subscriptions (issue #50) ------------------------------
	{Method: "GET", Path: "/api/v1/events", Group: "Events", Title: "List events", Summary: "The event catalog: every event a subscription can name — `name`, `scope` (app or install), `source`, `summary` and its data `fields`. The same list as docs/events.md (R-364). `destinations` lists the notification adapters a subscription can send through now (`id`, `name`, `kind`, `audience`: people or channel, and `channels`: whether a subscription to it names a channel, from GET /api/v1/notify/{adapterID}/channels)."},
	{Method: "GET", Path: "/api/v1/subscriptions", Group: "Events", Title: "List subscriptions", Summary: "Your event subscriptions, newest first. `app_id` narrows to one app; `everyone=true` lists every person's, which needs `install.events.manage`. `limit` (default 100, at most 500) and `cursor` page; `next_cursor` continues."},
	{Method: "POST", Path: "/api/v1/subscriptions", Group: "Events", Title: "Create a subscription", Summary: "Subscribe to events (`events`: names, prefixes such as `deploy.*`, or `*`) on one app (`app_id`, which needs `app.view`) or install-wide (no `app_id`, which needs `install.events.manage`), sent to a `webhook` (`url`) or through a notification adapter (`notify`, `adapter_id`, and `channel` for one whose destination says `channels`, such as Slack). A webhook's `signing_key` is in this response and never again (R-367, R-371)."},
	{Method: "GET", Path: "/api/v1/subscriptions/{subscriptionID}", Group: "Events", Title: "Get a subscription", Summary: "One subscription: its filter, destination, whether it is on, and why Pando turned it off if it did. Yours, or anybody's with `install.events.manage`."},
	{Method: "PATCH", Path: "/api/v1/subscriptions/{subscriptionID}", Group: "Events", Title: "Update a subscription", Summary: "Change a subscription's `events`, `url`, `adapter_id`, `channel` or `description`, or turn it on or off (`enabled`). Turning one on clears its record of failures."},
	{Method: "DELETE", Path: "/api/v1/subscriptions/{subscriptionID}", Group: "Events", Title: "Delete a subscription", Summary: "Delete a subscription, its signing key and its delivery log."},
	{Method: "POST", Path: "/api/v1/subscriptions/{subscriptionID}/signing-key", Group: "Events", Title: "Rotate a signing key", Summary: "Replace a webhook's signing key. The new `signing_key` is in this response and never again; deliveries not yet sent are signed with it."},
	{Method: "POST", Path: "/api/v1/subscriptions/{subscriptionID}/test", Group: "Events", Title: "Send a test event", Summary: "Send a `subscription.test` event to this subscription alone, whatever its filter says. Returns the queued delivery."},
	{Method: "GET", Path: "/api/v1/subscriptions/{subscriptionID}/deliveries", Group: "Events", Title: "List deliveries", Summary: "A subscription's deliveries, newest first: each event, its `status` (pending, succeeded, failed), attempts and last error. `before` and `limit` page; `next_before` continues (R-369)."},
	{Method: "GET", Path: "/api/v1/subscriptions/{subscriptionID}/deliveries/{deliveryID}", Group: "Events", Title: "Get a delivery", Summary: "One delivery: every attempt at it (`attempt_log`) and the `payload` sent."},
	{Method: "POST", Path: "/api/v1/subscriptions/{subscriptionID}/deliveries/{deliveryID}/redeliver", Group: "Events", Title: "Redeliver an event", Summary: "Send a delivery again now, with the whole retry schedule ahead of it."},
	{Method: "GET", Path: "/api/v1/me/notifications", Group: "Events", Title: "List notifications", Summary: "Your notifications inbox, newest first: what Pando told you on the console, each with `kind`, `subject`, `body`, `app_name`, `link` and `read_at`, and `unread`, how many are unread in all. `unread=true` lists only those; `before` and `limit` page (R-377)."},
	{Method: "GET", Path: "/api/v1/me/notifications/unread", Group: "Events", Title: "Count unread notifications", Summary: "How many of your notifications are unread, as `unread`, without listing any: the count the console's bell asks for (R-377)."},
	{Method: "POST", Path: "/api/v1/me/notifications/{notificationID}/read", Group: "Events", Title: "Mark a notification read", Summary: "Mark one of your notifications read."},
	{Method: "POST", Path: "/api/v1/me/notifications/read", Group: "Events", Title: "Mark all notifications read", Summary: "Mark every one of your notifications read."},
	{Method: "GET", Path: "/api/v1/notification-preferences", Group: "Events", Title: "Get notification preferences", Summary: "Which of Pando's own notifications reach you, on which channel: every `kind`, every `channel` that reaches people (the console, email), and your `choices` with defaults filled in (R-373)."},
	{Method: "PUT", Path: "/api/v1/notification-preferences", Group: "Events", Title: "Set notification preferences", Summary: "Set your notification preferences: `choices`, each a `kind`, a `channel` and `enabled`. Choices not sent keep their current value."},

	{Method: "GET", Path: "/api/v1/approvals", Group: "Deploys", Title: "List pending approvals", Summary: "Deploys waiting for approval on every app you can see, oldest first: each deployment with `app_name`, `app_slug`, its `approval_reasons`, the `approvals` so far, and `can_decide` — whether you may approve or reject it. `limit` (default 100, at most 500) and `cursor` page; `next_cursor` continues, and a page can hold fewer than `limit` and still have one."},

	// --- secrets ----------------------------------------------------------
	{Method: "GET", Path: "/api/v1/apps/{appID}/secrets", Group: "Secrets", Title: "List secrets", Summary: "Which secrets this app has, and where each came from. Never their values.", Verb: string(authz.AppView)},
	{Method: "PUT", Path: "/api/v1/apps/{appID}/secrets/{key}", Group: "Secrets", Title: "Set a secret", Summary: "Set a secret. Only a `secret_ref` in the spec brings it into the app: the reply's `read_by_spec` says whether the newest revision has one, and `note` says what to add when it does not. Rotating one the app reads recreates the workload on the next deploy rather than leaving it running with the old value (R-193).", Verb: string(authz.AppSecretsWrite)},
	{Method: "DELETE", Path: "/api/v1/apps/{appID}/secrets/{key}", Group: "Secrets", Title: "Delete a secret", Summary: "Remove a secret.", Verb: string(authz.AppSecretsWrite)},
	{Method: "GET", Path: "/api/v1/apps/{appID}/secrets/{key}/value", Group: "Secrets", Title: "Read a secret's value", Summary: "Read one secret's value. Its own verb, separate from managing the app, and audited every time (R-083).", Verb: string(authz.AppSecretsRead)},
	{Method: "GET", Path: "/api/v1/apps/{appID}/registry-credential", Group: "Secrets", Title: "Get the registry credential", Summary: "Whether the app has a credential for pulling its image, and of which `kind` (`basic` or `ecr`), with its `username` or `access_key_id` and `region`. Never the password or secret key.", Verb: string(authz.AppView)},
	{Method: "PUT", Path: "/api/v1/apps/{appID}/registry-credential", Group: "Secrets", Title: "Set the registry credential", Summary: "Set the credential the app's image is pulled with: `kind` `basic` with `username` and `password` (a token), or `kind` `ecr` with `access_key_id`, `secret_access_key` and optionally `region`, from which a registry password is minted for every pull. Replaces any credential the app had. It belongs to the app and is never given to it.", Verb: string(authz.AppSecretsWrite)},
	{Method: "DELETE", Path: "/api/v1/apps/{appID}/registry-credential", Group: "Secrets", Title: "Remove the registry credential", Summary: "Remove the app's registry credential, so its image is pulled anonymously.", Verb: string(authz.AppSecretsWrite)},

	// --- security ---------------------------------------------------------
	{Method: "GET", Path: "/api/v1/apps/{appID}/notices", Group: "Apps", Title: "List an app's notices", Summary: "What the app's Overview asks of somebody, computed when asked (R-412): `notices`, each with `key` (stable: `config.unshipped`, `security.below_threshold`, `backup.not_taken`, `variables.unset`, or `warning.` and a spec warning's code), `message`, `fingerprint` (changes exactly when what the notice says changes) and `ignored`, whether you have ignored it as it reads now. A caller that is not a person sees every notice unignored.", Verb: string(authz.AppView)},
	{Method: "PUT", Path: "/api/v1/apps/{appID}/notices/{key}/ignore", Group: "Apps", Title: "Ignore a notice", Summary: "Hide a notice from yourself until what it says changes (R-412). Answers with the notice. Yours only: everyone else still sees it. Hides a reminder and nothing more: a deploy the notice warned about is refused for the same reason. `NOT_FOUND` when the app has no such notice now.", Verb: string(authz.AppView)},
	{Method: "DELETE", Path: "/api/v1/apps/{appID}/notices/{key}/ignore", Group: "Apps", Title: "Restore a notice", Summary: "Show a notice you ignored again (R-412). Restoring one that is not ignored is not an error.", Verb: string(authz.AppView)},
	{Method: "GET", Path: "/api/v1/apps/{appID}/security", Group: "Security", Title: "Get the security score", Summary: "The app's security score, what it was taken from, and the findings behind it (R-310). `scope` says what the scan read: `source`, `image` or `image_and_source`. `awaiting_image` says the scan read the source alone before anything was built, so `standing.score` is empty until a scan reads the image the app runs, and `scan.score` is the source's (R-311).", Verb: string(authz.AppView)},
	{Method: "POST", Path: "/api/v1/apps/{appID}/security/scan", Group: "Security", Title: "Scan an app", Summary: "Scan the app now. A write, not a refresh: the score decides whether the next deploy is allowed (R-312, R-314).", Verb: string(authz.AppDeploy)},

	// --- sharing ----------------------------------------------------------
	{Method: "GET", Path: "/api/v1/apps/{appID}/events", Group: "Events", Title: "List an app's events", Summary: "The app's recent events, newest first: each as a webhook receives it (`id`, `type`, `occurred_at`, `actor`, `data`, `link`) and as a person reads it (`actor_name`, the person who acted or a token acted for; `subject`, `body`, `fields`). `before` and `limit` page. Kept as long as the event outbox keeps them, 30 days (R-378).", Verb: string(authz.AppView)},
	{Method: "GET", Path: "/api/v1/apps/{appID}/grants", Group: "Sharing", Title: "List grants", Summary: "Who can reach this app, and who can administer it — two planes, listed separately (R-070, R-071). By principal, the grant to everyone first, with each principal's grants on both planes on the same page: `limit` (default 100, at most 500) and `cursor` page; `next_cursor` continues.", Verb: string(authz.AppView)},
	{Method: "POST", Path: "/api/v1/apps/{appID}/grants", Group: "Sharing", Title: "Share an app", Summary: "Share the app with a user, a group, a token, or with everyone. The anonymous grant is a real row, refused where host policy forbids it (R-075, R-076).", Verb: string(authz.AppGrantsManage)},
	{Method: "PATCH", Path: "/api/v1/apps/{appID}/grants/{grantID}", Group: "Sharing", Title: "Change a grant's role", Summary: "Change the role a grant for managing the app carries (`role_id`), one update so the person is never left with nothing in between; or, on the grant to everyone, set `passcode` (\"\" removes it). A new passcode asks everyone let in by the old one again (R-075a).", Verb: string(authz.AppGrantsManage)},
	{Method: "GET", Path: "/api/v1/apps/{appID}/principals", Group: "Sharing", Title: "Find people to share with", Summary: "People and groups to share the app with, matching `q` (username, name or email; group name), at most 20 of each.", Verb: string(authz.AppGrantsManage)},
	{Method: "GET", Path: "/api/v1/apps/{appID}/passcode", Group: "Sharing", Title: "Get a passcode prompt", Summary: "The name of an app that asks for a passcode, for its passcode page. Public; not-found for any other app (R-075a).", Public: true},
	{Method: "POST", Path: "/api/v1/apps/{appID}/passcode", Group: "Sharing", Title: "Enter a passcode", Summary: "Enter an app's passcode (`passcode`). Right, and the browser is let in for a day by a cookie the app never sees; ten wrong tries in fifteen minutes and it waits. Public (R-075a).", Public: true},
	{Method: "DELETE", Path: "/api/v1/apps/{appID}/grants/{grantID}", Group: "Sharing", Title: "Remove a grant", Summary: "Take a grant away.", Verb: string(authz.AppGrantsManage)},

	// --- accounts, groups, roles -----------------------------------------
	{Method: "GET", Path: "/api/v1/users", Group: "Identity", Title: "List accounts", Summary: "The accounts on this installation, newest first. Each carries `install_roles`, every installation role it holds as `{role_id, via}` — `via.kind` is `direct`, or `group` with the group's `group_id`, `name` and, for a group synced from a provider, `source` and `source_name` — read as authorization reads them, through linked provider groups too; and `install_role_id`, the role granted to the account itself (empty for none). `limit` (default 100, at most 500) and `cursor` page; `next_cursor` continues; `q` matches the username, display name or email; `id`, repeatable, reads only those accounts; `total` counts the matches exactly up to 10,000; past that it is 10,000 and `total_is_lower_bound` is true (O-53).", Verb: string(authz.InstallView)},
	{Method: "POST", Path: "/api/v1/users", Group: "Identity", Title: "Create an account", Summary: "Create an account.", Verb: string(authz.InstallUsersManage)},
	{Method: "GET", Path: "/api/v1/users/{userID}", Group: "Identity", Title: "Get an account", Summary: "One account, as GET /users shows it, with every installation role it holds and where each comes from (`install_roles`). Your own needs no verb.", Verb: string(authz.InstallView)},
	{Method: "PATCH", Path: "/api/v1/users/{userID}", Group: "Identity", Title: "Update an account", Summary: "Change an account: any of `username`, `display_name`, `email` and `status`. Username and email only on a local account; a username only with this verb, even your own. Suspension is not deletion (R-049). Your own name and email need no verb. On someone else's account, refused unless the caller holds every installation permission that account holds (R-080a).", Verb: string(authz.InstallUsersManage)},
	{Method: "DELETE", Path: "/api/v1/users/{userID}", Group: "Identity", Title: "Delete an account", Summary: "Delete an account, with the destruction rules that follow from it (R-282). On someone else's account, refused unless the caller holds every installation permission that account holds (R-080a).", Verb: string(authz.InstallUsersManage)},
	{Method: "PUT", Path: "/api/v1/users/{userID}/role", Group: "Identity", Title: "Set an account's role", Summary: "Give an account an installation role. Deliberately not a field on PATCH: changing someone's status and changing their power are different acts. Refused unless the caller holds every installation permission the role carries (R-080a). And on someone else's account, refused unless the caller holds every installation permission that account holds (R-080a).", Verb: string(authz.InstallUsersManage)},
	{Method: "DELETE", Path: "/api/v1/users/{userID}/role", Group: "Identity", Title: "Remove an account's role", Summary: "Take an installation role away. The last administrator cannot be demoted. On someone else's account, refused unless the caller holds every installation permission that account holds (R-080a).", Verb: string(authz.InstallUsersManage)},
	{Method: "GET", Path: "/api/v1/users/{userID}/app-limit", Group: "Identity", Title: "Get an account's app limit", Summary: "How many apps an account may own (R-244): `limit` (0 is unlimited), where it comes from (`source`: user, group or policy, with `group_id` and `group_name` for a group), how many it owns (`owned`), and the value set on the account itself (`max_apps`, null when none is). Your own needs no verb.", Verb: string(authz.InstallUsersManage)},
	{Method: "PUT", Path: "/api/v1/users/{userID}/app-limit", Group: "Identity", Title: "Set an account's app limit", Summary: "Set `max_apps` on an account: a number, 0 for unlimited, or null to clear it. It applies whatever the account's groups say. Lowering it below what the account owns removes nothing; it refuses the next app (R-244).", Verb: string(authz.InstallUsersManage)},
	{Method: "DELETE", Path: "/api/v1/users/{userID}/two-factor", Group: "Identity", Title: "Reset two-factor authentication", Summary: "Remove another local account's authenticator and recovery codes, for someone who has lost both, ending every session it holds. They sign in with their password alone, and set two-factor authentication up again there if host policy requires it. Your own is DELETE /me/two-factor. Refused unless the caller holds every installation permission that account holds (R-080a, R-405).", Verb: string(authz.InstallUsersManage)},
	{Method: "POST", Path: "/api/v1/users/{userID}/password", Group: "Identity", Title: "Reset a password", Summary: "Reset another local account's password (`password`), ending every session it holds. `must_change_password` defaults to true: whoever set it hands it over, and its holder chooses their own at the next sign-in. Your own is `POST /me/password`. On someone else's account, refused unless the caller holds every installation permission that account holds (R-080a).", Verb: string(authz.InstallUsersManage)},
	{Method: "POST", Path: "/api/v1/passwords/generate", Group: "Identity", Title: "Generate a password", Summary: "A strong random password, 18 to 22 characters with upper and lower case, digits and symbols, for creating or resetting an account. Stores nothing.", Verb: string(authz.InstallUsersManage)},
	{Method: "GET", Path: "/api/v1/users/{userID}/apps", Group: "Identity", Title: "List an account's apps", Summary: "The apps an account has something on: its role for managing each, directly or through a group, whether it can use each, and whether you can change that (`can_manage`). Only apps you can see are listed. Your own needs nothing. By app name, a page of apps at a time: `limit` (default 100, at most 500) and `cursor` page; `next_cursor` continues, and a page can hold fewer apps than the limit when some are ones you cannot see.", Verb: string(authz.InstallView)},
	{Method: "GET", Path: "/api/v1/groups", Group: "Identity", Title: "List groups", Summary: "Groups, whether Pando's own or an identity adapter's (R-078), Pando's first and then by name, each with `member_count`; GET /groups/{groupID} has the members. `limit` (default 100, at most 500) and `cursor` page; `next_cursor` continues; `q` matches the name; `member` keeps the groups an account is directly in; `total` counts the matches exactly up to 10,000; past that it is 10,000 and `total_is_lower_bound` is true (O-53).", Verb: string(authz.InstallView)},
	{Method: "POST", Path: "/api/v1/groups", Group: "Identity", Title: "Create a group", Summary: "Create a group.", Verb: string(authz.InstallUsersManage)},
	{Method: "PUT", Path: "/api/v1/groups/{groupID}/members", Group: "Identity", Title: "Set group members", Summary: "Set a group's members. Refused unless the caller holds every installation permission the group's role carries (R-080a).", Verb: string(authz.InstallUsersManage)},
	{Method: "GET", Path: "/api/v1/groups/{groupID}/members", Group: "Identity", Title: "List group members", Summary: "The accounts directly in a group, oldest first, each as GET /users shows it. `limit` (default 100, at most 500) and `cursor` page; `next_cursor` continues; `q` matches the username, display name or email; `id`, repeatable, keeps only those accounts, which answers whether they are members. `total` counts the matches exactly up to 10,000; past that it is 10,000 and `total_is_lower_bound` is true (O-53).", Verb: string(authz.InstallView)},
	{Method: "PUT", Path: "/api/v1/groups/{groupID}/members/{userID}", Group: "Identity", Title: "Add a group member", Summary: "Add one account to a group. It then holds everything the group holds. Refused unless the caller holds every installation permission the group's role carries (R-080a).", Verb: string(authz.InstallUsersManage)},
	{Method: "DELETE", Path: "/api/v1/groups/{groupID}/members/{userID}", Group: "Identity", Title: "Remove a group member", Summary: "Remove one account from a group. Refused when it would leave nobody who can manage accounts (R-088). Refused unless the caller holds every installation permission the group's role carries (R-080a).", Verb: string(authz.InstallUsersManage)},
	{Method: "PUT", Path: "/api/v1/groups/{groupID}/role", Group: "Identity", Title: "Set a group's role", Summary: "Give a group an installation role (`role_id`), which everyone in it holds. Refused unless the caller holds every installation permission the role carries (R-080a). So does replacing the group's current role.", Verb: string(authz.InstallUsersManage)},
	{Method: "DELETE", Path: "/api/v1/groups/{groupID}/role", Group: "Identity", Title: "Remove a group's role", Summary: "Take a group's installation role away. Refused when it would leave nobody who can manage accounts (R-088). Refused unless the caller holds every installation permission the group's role carries (R-080a).", Verb: string(authz.InstallUsersManage)},
	{Method: "GET", Path: "/api/v1/users/{userID}/identities", Group: "Identity", Title: "List linked identities", Summary: "The external identities that sign in to an account: which provider, its ID for the person, whether it is where the account came from, and whether SCIM manages it. Your own, or anyone's with install.view."},
	{Method: "POST", Path: "/api/v1/users/{userID}/identities", Group: "Identity", Title: "Link an identity", Summary: "Link a provider's identity (`adapter_id`, `external_id`) to an account, so it signs in there. Adds an alias and never merges accounts (O-1). If it already signs in to another account, `replace_account: true` moves it, and that account is kept, suspended, as an alias. When that account is the last active owner of an app, refused unless `confirm: true`, naming the apps (R-409). On someone else's account, refused unless the caller holds every installation permission that account holds (R-080a).", Verb: string(authz.InstallUsersManage)},
	{Method: "DELETE", Path: "/api/v1/users/{userID}/identities", Group: "Identity", Title: "Unlink an identity", Summary: "Unlink an identity (`adapter_id`, `external_id` in the query) from an account. On someone else's account, refused unless the caller holds every installation permission that account holds (R-080a).", Verb: string(authz.InstallUsersManage)},
	{Method: "PUT", Path: "/api/v1/groups/{groupID}/links/{syncedGroupID}", Group: "Identity", Title: "Link a synced group", Summary: "Make everyone in a group an identity provider syncs count as a member of a group made in Pando, live (R-078, R-079). Refused unless the caller holds every installation permission the group's role carries (R-080a).", Verb: string(authz.InstallUsersManage)},
	{Method: "DELETE", Path: "/api/v1/groups/{groupID}/links/{syncedGroupID}", Group: "Identity", Title: "Unlink a synced group", Summary: "Remove such a link. Refused when it would leave nobody who can manage accounts (R-088). Refused unless the caller holds every installation permission the group's role carries (R-080a).", Verb: string(authz.InstallUsersManage)},

	// --- identity providers -------------------------------------------------
	{Method: "GET", Path: "/api/v1/identity-providers", Group: "Identity providers", Title: "List identity providers", Summary: "Every identity provider, local accounts included: settings, which credentials are set (never their values), the callback URL and entity ID to register with the provider, the SCIM base URL, and its revocation — session lifetime, mode, and the window that results (R-047, R-050). `kinds` describes the kinds that can be added, with presets for known providers. `endpoints` gives a new provider's `callback_url` and `entity_id` with `{id}` for the ID it is created with, so they can be registered with the provider before it is saved.", Verb: string(authz.InstallView)},
	{Method: "POST", Path: "/api/v1/identity-providers", Group: "Identity providers", Title: "Add an identity provider", Summary: "Add an identity provider: `kind` (oidc or saml), `name`, `config`, write-only `credentials`, `jit_provisioning`, `link_by_email`. Off until `enabled` is set, so it can be tested first. Needs every installation permission, because a provider decides who signs in as which account (R-080a). `id` may be given, an `idp_` ULID not yet used, to create it with the ID its registered addresses were built from.", Verb: string(authz.InstallAdaptersManage)},
	{Method: "GET", Path: "/api/v1/identity-providers/{providerID}", Group: "Identity providers", Title: "Get an identity provider", Summary: "One identity provider.", Verb: string(authz.InstallView)},
	{Method: "PATCH", Path: "/api/v1/identity-providers/{providerID}", Group: "Identity providers", Title: "Update an identity provider", Summary: "Change an identity provider. `config` replaces the settings whole; each `credentials` field replaces that one, and an empty value removes it. Takes effect on the next sign-in, without a restart. Needs every installation permission, because a provider decides who signs in as which account (R-080a).", Verb: string(authz.InstallAdaptersManage)},
	{Method: "DELETE", Path: "/api/v1/identity-providers/{providerID}", Group: "Identity providers", Title: "Remove an identity provider", Summary: "Remove an identity provider nobody has signed in through. One that has is turned off instead.", Verb: string(authz.InstallAdaptersManage)},
	{Method: "POST", Path: "/api/v1/identity-providers/{providerID}/check", Group: "Identity providers", Title: "Check an identity provider", Summary: "Whether the provider answers: its discovery document or metadata can be read (`ok`, `message`).", Verb: string(authz.InstallAdaptersManage)},
	{Method: "POST", Path: "/api/v1/identity-providers/{providerID}/scim-token", Group: "Identity providers", Title: "Turn on SCIM", Summary: "Turn SCIM on for a provider, or replace its token. The token is in this response and never again. With SCIM on, the provider's pushes create and suspend accounts and set its groups' members at once (R-048). Needs every installation permission, because a provider decides who signs in as which account (R-080a).", Verb: string(authz.InstallAdaptersManage)},
	{Method: "DELETE", Path: "/api/v1/identity-providers/{providerID}/scim-token", Group: "Identity providers", Title: "Turn off SCIM", Summary: "Turn SCIM off for a provider. What it pushed stays.", Verb: string(authz.InstallAdaptersManage)},
	{Method: "GET", Path: "/api/v1/identity-providers/{providerID}/test", Group: "Identity providers", Title: "Start a test sign-in", Summary: "Start a test sign-in: a browser navigation to the provider, returning to the console with a report of the claims it sent and what Pando would do with them. Signs nobody in, and works while the provider is off.", Verb: string(authz.InstallAdaptersManage)},
	{Method: "GET", Path: "/api/v1/identity-providers/{providerID}/tests/{flowID}", Group: "Identity providers", Title: "Get a test sign-in report", Summary: "A test sign-in's report, to the administrator who ran it.", Verb: string(authz.InstallAdaptersManage)},

	// --- SCIM ---------------------------------------------------------------
	{Method: "GET", Path: "/api/v1/scim/v2/ServiceProviderConfig", Group: "SCIM", Title: "Get SCIM configuration", Summary: "SCIM 2.0 service provider configuration. Every SCIM endpoint takes the provider's SCIM token as a bearer token, not a Pando token."},
	{Method: "GET", Path: "/api/v1/scim/v2/ResourceTypes", Group: "SCIM", Title: "List SCIM resource types", Summary: "SCIM resource types: User and Group."},
	{Method: "GET", Path: "/api/v1/scim/v2/Schemas", Group: "SCIM", Title: "List SCIM schemas", Summary: "The SCIM attributes Pando reads."},
	{Method: "GET", Path: "/api/v1/scim/v2/Users", Group: "SCIM", Title: "List SCIM users", Summary: "The accounts this provider provisioned. `filter` takes `userName`, `externalId` or `emails` with `eq`; `startIndex` and `count` page."},
	{Method: "POST", Path: "/api/v1/scim/v2/Users", Group: "SCIM", Title: "Provision a user", Summary: "Provision an account. An account the provider's sign-in already made is adopted rather than refused."},
	{Method: "GET", Path: "/api/v1/scim/v2/Users/{id}", Group: "SCIM", Title: "Get a SCIM user", Summary: "One provisioned account."},
	{Method: "PUT", Path: "/api/v1/scim/v2/Users/{id}", Group: "SCIM", Title: "Replace a SCIM user", Summary: "Replace an account's profile. `active: false` suspends it and ends its sessions at once; `active: true` lifts only a suspension this provider made (R-049)."},
	{Method: "PATCH", Path: "/api/v1/scim/v2/Users/{id}", Group: "SCIM", Title: "Patch a SCIM user", Summary: "Change an account's profile or `active` with SCIM PATCH operations."},
	{Method: "DELETE", Path: "/api/v1/scim/v2/Users/{id}", Group: "SCIM", Title: "Deprovision a user", Summary: "Deprovision an account: it is suspended, not deleted (R-049), leaves the provider's groups, and its sessions end."},
	{Method: "GET", Path: "/api/v1/scim/v2/Groups", Group: "SCIM", Title: "List SCIM groups", Summary: "This provider's groups. `filter` takes `displayName` or `externalId` with `eq`; `excludedAttributes=members` leaves members out."},
	{Method: "POST", Path: "/api/v1/scim/v2/Groups", Group: "SCIM", Title: "Push a group", Summary: "Push a group. It holds no access until an administrator gives it some or links it to a Pando group (R-078)."},
	{Method: "GET", Path: "/api/v1/scim/v2/Groups/{id}", Group: "SCIM", Title: "Get a SCIM group", Summary: "One pushed group, with its members."},
	{Method: "PUT", Path: "/api/v1/scim/v2/Groups/{id}", Group: "SCIM", Title: "Replace a SCIM group", Summary: "Replace a pushed group's name and members."},
	{Method: "PATCH", Path: "/api/v1/scim/v2/Groups/{id}", Group: "SCIM", Title: "Patch a SCIM group", Summary: "Add or remove members, or rename, with SCIM PATCH operations. Takes effect on the next request (R-079)."},
	{Method: "DELETE", Path: "/api/v1/scim/v2/Groups/{id}", Group: "SCIM", Title: "Delete a SCIM group", Summary: "Delete a pushed group, and every grant made to it."},
	{Method: "GET", Path: "/api/v1/groups/{groupID}/apps", Group: "Identity", Title: "List a group's apps", Summary: "A group's app grants: the role everyone in it has on each app, whether they can open it, and whether you can change that (`can_manage`). Only apps you can see. Share an app with a group through `POST /apps/{appID}/grants` with `principal_kind: group`. By app name, a page of apps at a time: `limit` (default 100, at most 500) and `cursor` page; `next_cursor` continues.", Verb: string(authz.InstallView)},
	{Method: "GET", Path: "/api/v1/groups/{groupID}/app-limit", Group: "Identity", Title: "Get a group's app limit", Summary: "How many apps each member of a group may own: `max_apps`, 0 for unlimited, or null when the group sets none (R-244).", Verb: string(authz.InstallUsersManage)},
	{Method: "PUT", Path: "/api/v1/groups/{groupID}/app-limit", Group: "Identity", Title: "Set a group's app limit", Summary: "Set a group's `max_apps`: a number, 0 for unlimited, or null to clear it. A person in several groups gets the most generous; a value on their own account beats every group (R-244).", Verb: string(authz.InstallUsersManage)},
	{Method: "GET", Path: "/api/v1/groups/{groupID}", Group: "Identity", Title: "Get a group", Summary: "One group with its `member_count` (direct members), its `linked_from` or `links_to`, and where it comes from. The members are GET /groups/{groupID}/members.", Verb: string(authz.InstallView)},
	{Method: "DELETE", Path: "/api/v1/groups/{groupID}", Group: "Identity", Title: "Delete a group", Summary: "Delete a group. Everything shared with it goes with it: its members lose that access and keep anything given to them another way. Refused if it would leave nobody who can manage accounts (R-088). Refused unless the caller holds every installation permission the group's role carries (R-080a).", Verb: string(authz.InstallUsersManage)},
	{Method: "GET", Path: "/api/v1/roles", Group: "Identity", Title: "List roles", Summary: "Roles, built in and custom. By default the ones granted across the installation; `scope=app` gives the ones granted on an app, and `scope=all` both. Built-in roles are immutable (R-081).", Verb: string(authz.InstallView)},
	{Method: "POST", Path: "/api/v1/roles", Group: "Identity", Title: "Create a role", Summary: "Compose a custom role from verbs (R-082). An installation role may carry only installation permissions the caller holds (R-080a).", Verb: string(authz.InstallUsersManage)},
	{Method: "DELETE", Path: "/api/v1/roles/{roleID}", Group: "Identity", Title: "Delete a role", Summary: "Delete a custom role, and every grant of it: whoever held it loses what it allowed. Built-in roles cannot be deleted (R-081). Refused if it would leave nobody who can manage accounts (R-088). Refused unless the caller holds every installation permission the role carries (R-080a).", Verb: string(authz.InstallUsersManage)},
	{Method: "GET", Path: "/api/v1/verbs", Group: "Identity", Title: "List verbs", Summary: "Every verb, by scope, for composing a role. There is no implication graph: holding one says nothing about another (R-082).", Verb: string(authz.InstallView)},

	// --- installation -----------------------------------------------------
	{Method: "GET", Path: "/api/v1/adapters", Group: "Installation", Title: "List adapters", Summary: "The adapters configured here and what they can currently do — live capabilities, not stored configuration. Names which credentials are set, never their values. `pending_restart` marks one saved since Pando started, which is not yet what runs; `restart_needed` says any is. A routing adapter Pando runs a process in front of itself for — Traefik, cloudflared — has `edge`: whether it is running, and why not to whoever may change it (R-174). An image registry is signed in to for its health, and has `capabilities` like a runtime. An image registry may also have `notes`: what works but will not do what an operator expects, such as a credential that cannot delete, so a deleted app's images stay behind.", Verb: string(authz.InstallView)},
	{Method: "GET", Path: "/api/v1/adapters/kinds", Group: "Installation", Title: "List adapter kinds", Summary: "The kinds of adapter this build of Pando can run, and the settings each takes — which are credentials (write-only, stored encrypted), which are required, the default each takes when left empty or an example, and which are `advanced`: less common, never required, always with a default, and asked for apart from the rest.", Verb: string(authz.InstallView)},
	{Method: "POST", Path: "/api/v1/restart", Group: "Installation", Title: "Restart Pando", Summary: "Restart Pando: finish the requests in flight, then start again, loading the adapters and the configuration file afresh. Apps behind Pando are unreachable for the seconds it takes. Environment variables are not re-read. Returns before the restart; `started_at` on GET /api/v1/adapters changes once it is back.", Verb: string(authz.InstallAdaptersManage)},
	{Method: "POST", Path: "/api/v1/adapters", Group: "Installation", Title: "Configure an adapter", Summary: "Configure an adapter. Settings go in config; credentials such as an API key go in credentials, which is write-only and stored encrypted. A source connection (category `source`) and an image registry (category `image_registry`) are used from the moment they are saved, with no restart; an image registry Pando could not push to is refused before it is saved. An audit sink (category `audit_sink`) is used from the next delivery pass too, is refused when its settings are, and needs `install.audit.export` as well, because it sends the audit log off the installation (R-385). `warnings` lists what saved but may not work as wanted, such as a Cloudflare console hostname its included certificate does not cover; a warning never refuses a save. `is_default` makes it the default of its category in place of the current one, in one step: `replaced_default` names the adapter that stopped being the default, and `handover` says what that changes. Through the API, an adapter's `*_env` setting may name only its kind's default variable, and an adapter that would read its key from Pando's environment may not be pointed at another `base_url` without a stored key (R-080a).", Verb: string(authz.InstallAdaptersManage)},

	// --- sources ----------------------------------------------------------
	{Method: "GET", Path: "/api/v1/sources", Group: "Sources", Title: "List source connections", Summary: "The installation's source connections (R-091): each one's `id`, `name`, `kind` and `capabilities` — its `method`, `host`, `scope`, whether it can list repositories, which OAuth flows it can run, and whether it is `authorized`. `problem` says why one cannot be used. A private repository is read with the connection that covers it most closely; add one with POST /adapters, category `source`.", Verb: string(authz.AppCreate)},
	{Method: "GET", Path: "/api/v1/sources/{sourceID}/repositories", Group: "Sources", Title: "List repositories", Summary: "The repositories a connection can read, to pick one rather than type its address: `url`, `full_name`, `default_branch`, `private`. `q` matches part of the name and `limit` caps the list (default 100). Repositories the source allowlist refuses are left out (R-092). Refused for a connection with no API access, such as an SSH key.", Verb: string(authz.AppCreate)},
	{Method: "GET", Path: "/api/v1/sources/{sourceID}/branches", Group: "Sources", Title: "List branches", Summary: "The branches of the repository at `url`, through the connection.", Verb: string(authz.AppCreate)},
	{Method: "DELETE", Path: "/api/v1/sources/{sourceID}", Group: "Sources", Title: "Disconnect a source", Summary: "Disconnect a source connection and remove its stored credential. Apps read with it keep running; their next deploy fails, saying the connection is gone (R-146).", Verb: string(authz.InstallAdaptersManage)},
	{Method: "POST", Path: "/api/v1/sources/{sourceID}/authorize", Group: "Sources", Title: "Authorize a source", Summary: "Start an OAuth authorization of a connection, or create and install its GitHub App. `mode` `device` (the default) returns `user_code` and `verification_url` to show, and `interval_seconds` to poll POST /authorize/poll at; it needs no address the provider can reach. `mode` `web` returns `authorize_url` to send the browser to, which comes back to GET /api/v1/sources/callback. A GitHub App connection is web only: while its App is not created yet the answer also has `form`, an `action` and `fields` the browser posts to GitHub, and `authorize_url` is the console page that posts it. Once created, the App is installed next, and GitHub returns to GET /api/v1/sources/{sourceID}/installed.", Verb: string(authz.InstallAdaptersManage)},
	{Method: "GET", Path: "/api/v1/sources/{sourceID}/installed", Group: "Sources", Title: "GitHub App installed", Summary: "Where GitHub returns the browser once the App Pando created for a connection is installed: the App's setup URL. Keeps `installation_id` once the App's own token confirms it is an installation of that App, and redirects to the console's Adapters screen with `authorized` or `error`.", Verb: string(authz.InstallAdaptersManage)},
	{Method: "POST", Path: "/api/v1/sources/{sourceID}/webhook", Group: "Sources", Title: "GitHub App webhook", Summary: "Where the GitHub App Pando created for a connection sends push and release events (R-142), signed with the App's webhook secret in `X-Hub-Signature-256`. A verified delivery starts a check of each app that deploys automatically from the repository it names and the ref it moved (202); anything else is ignored (200). Public: the signature is the credential.", Public: true},
	{Method: "POST", Path: "/api/v1/sources/{sourceID}/authorize/poll", Group: "Sources", Title: "Poll a source authorization", Summary: "Ask once whether a device authorization was approved: `status` is `pending` (with `slow_down` when the provider asked for slower polling) or `authorized`, when the token is stored and the connection usable.", Verb: string(authz.InstallAdaptersManage)},
	{Method: "GET", Path: "/api/v1/sources/callback", Group: "Sources", Title: "Source OAuth callback", Summary: "Where a provider returns a browser authorization. Stores the token and redirects to the console's Adapters screen with `authorized` or `error`.", Verb: string(authz.InstallAdaptersManage)},
	{Method: "GET", Path: "/api/v1/capacity", Group: "Installation", Title: "Get capacity", Summary: "What the host has, and what is committed to apps (R-242).", Verb: string(authz.InstallView)},
	{Method: "GET", Path: "/api/v1/policy", Group: "Installation", Title: "Get host policy", Summary: "Host policy. Reading the rules you work under is not the same privilege as changing them (R-274).", Verb: string(authz.InstallView)},
	{Method: "PUT", Path: "/api/v1/policy", Group: "Installation", Title: "Replace host policy", Summary: "Replace host policy. Policy is a floor, never an override (R-272).", Verb: string(authz.InstallPolicyManage)},
	{Method: "GET", Path: "/api/v1/ai/functions", Group: "Installation", Title: "List AI functions", Summary: "List every AI function, the adapter that handles it and on which model, whether it is on, and whether the startup configuration assigns it (R-259, R-271).", Verb: string(authz.InstallView)},
	{Method: "PUT", Path: "/api/v1/ai/functions/{function}", Group: "Installation", Title: "Assign an AI function", Summary: "Assign an AI function to an adapter, optionally on a model of its own. Refused while another adapter handles it (R-259).", Verb: string(authz.InstallAdaptersManage)},
	{Method: "DELETE", Path: "/api/v1/ai/functions/{function}", Group: "Installation", Title: "Turn off an AI function", Summary: "Turn an AI function off by removing its assignment (R-259).", Verb: string(authz.InstallAdaptersManage)},
	{Method: "POST", Path: "/api/v1/ai/access/draft", Group: "Installation", Title: "Draft access with AI", Summary: "Draft a custom role and a group from a description, with verbs from the catalog only. Body: `description`, and `current` with the draft so far to refine it. A draft: create it with POST /roles and POST /groups (R-343).", Verb: string(authz.InstallUsersManage)},
	{Method: "POST", Path: "/api/v1/ai/policy/draft", Group: "Installation", Title: "Draft policy with AI", Summary: "Propose host policy from a description: the document as it would be saved, and each change. Fields fixed in the startup configuration are declined, naming where. Body: `description`, and `proposed` with the document so far to refine it. Save it with PUT /policy (R-344).", Verb: string(authz.InstallPolicyManage)},
	{Method: "POST", Path: "/api/v1/ai/audit/search", Group: "Installation", Title: "Search audit log with AI", Summary: "Turn a question into audit filters, run them, and summarize what they found. Body: `question`. The filters are ordinary GET /audit parameters (R-345).", Verb: string(authz.InstallAuditRead)},
	{Method: "POST", Path: "/api/v1/ai/reference/answer", Group: "Reference", Title: "Answer a question with AI", Summary: "Answer a \"How can I…\" question from this reference, citing the endpoints, commands and tools it relies on. Body: `question`. Describes; does nothing (R-346)."},
	{Method: "POST", Path: "/api/v1/policy/preview", Group: "Installation", Title: "Preview a policy", Summary: "Which apps a candidate policy would block, before it is saved.", Verb: string(authz.InstallPolicyManage)},
	{Method: "GET", Path: "/api/v1/config", Group: "Installation", Title: "Get startup configuration", Summary: "The configuration Pando started with (R-271): every non-secret setting, its value and where it came from — an environment variable, the config file, or the default — and the host policy fields fixed there, which cannot be changed through the API while they are set. Secrets are never listed.", Verb: string(authz.InstallView)},
	{Method: "GET", Path: "/api/v1/audit", Group: "Installation", Title: "List audit events", Summary: "The audit log, newest first. Filters combine: `action` (a prefix), `principal_id` (who did it, including through a token), `principal_kind` (user, token, system or anonymous), `app_id`, `target_kind` and `target_id` (what it was done to), `involving` (an ID that is the actor or the target — everything to do with one account), and `since`/`until` (RFC 3339; since inclusive, until exclusive). Pages with `before`. Append-only: no endpoint edits or deletes an event, and the database refuses it too (R-027). Each event carries `outcome` (success, denied or failed), `source_ip`, `peer_ip`, `user_agent`, `actor_name`, `actor_email` and `schema_version` (R-379). Reading the log is itself audited, as `audit.read` (R-388).", Verb: string(authz.InstallAuditRead)},
	{Method: "GET", Path: "/api/v1/audit/stream", Group: "Installation", Title: "Stream the audit log", Summary: "The audit log in commit order, oldest first, from a cursor (R-381): for a collector that must miss nothing across restarts, upgrades and replicas. `after` is the `cursor` a previous read returned; empty starts at the oldest event in the live log, and `now` after the newest. `limit` (default 500, at most 1000); `wait` (0–60 seconds) holds the request until an event arrives; `action` and `exclude` are repeatable prefixes, and the cursor moves past what they drop; `format` is `native` (the archive's line format) or `ocsf`. Answers `events`, `cursor` and `caught_up`. Delivery is at least once: an event's `id` is its idempotency key. Audited as `audit.read` at most once an hour per reader (R-388).", Verb: string(authz.InstallAuditRead)},
	{Method: "GET", Path: "/api/v1/audit/export", Group: "Installation", Title: "Export the audit log", Summary: "Any range of the live log as gzipped JSON lines, in commit order (R-387): `since` and `until` (RFC 3339), `action` and `exclude` prefixes, and `format` `native` (the archive's line format) or `ocsf`. When the range reaches before the live log, `Pando-Audit-Live-From` names its oldest event's time, and archives hold the rest. Audited as `audit.export`.", Verb: string(authz.InstallAuditRead)},
	{Method: "GET", Path: "/api/v1/audit/sinks", Group: "Installation", Title: "List audit sinks", Summary: "Every audit sink — a destination the log is pushed to as it is written (R-382) — with what it sends where (`transport`, `endpoint`, `format`, `actions`, `exclude`, and `disclosure`, the sentence the console shows), its last delivered event (`cursor_at`, `delivered_at`, `delivered_count`), `backlog`, `last_error`, `failing_since`, `disabled_at` and `disabled_reason` when Pando turned it off, and `gap_from`/`gap_to` for a range it missed (R-383, R-386). Audit sinks are adapters of category `audit_sink`, created with `POST /adapters`, which needs `install.audit.export` for them (R-385).", Verb: string(authz.InstallAuditRead)},
	{Method: "GET", Path: "/api/v1/audit/archives", Group: "Installation", Title: "List audit archives", Summary: "The months of the audit log past retention, archived and removed from the live log (R-347). Each with its manifest: `month`, `row_count`, `first_id` and `last_id`, `first_at` and `last_at`, `size_bytes`, `sha256`, and where it is kept — `adapter_ref` when exported to a backup destination, absent when Pando keeps it. Retention is host policy's `audit_retention_months` (at least 3) and `audit_archive` (keep, export or off).", Verb: string(authz.InstallAuditRead)},
	{Method: "GET", Path: "/api/v1/updates", Group: "Installation", Title: "Show updates", Summary: "Whether a newer Pando is released (R-351): `current`, `latest`, `available`, and `releases`, each version after the running one, newest first, with its changelog section as `notes` and `security` and `breaking` marked. `upgrade` says how to move this installation to `latest`. `enabled` and `channel` are host policy's `disable_update_check` and `update_channel`; while the check is off Pando sends no request and reports nothing. `error` says why the last check failed. Every response to a signed-in caller carries the server's version as `Pando-Version`.", Verb: string(authz.InstallView)},
	{Method: "POST", Path: "/api/v1/updates/check", Group: "Installation", Title: "Check for updates now", Summary: "Asks GitHub for the release list now rather than at the next six-hourly check (R-349), and answers as `GET /updates` does. A request within a minute of the last check sends nothing and answers from that one. While host policy's `disable_update_check` is set, nothing is sent and `enabled` is false.", Verb: string(authz.InstallView)},
	{Method: "GET", Path: "/api/v1/upgrade", Group: "Installation", Title: "Plan an upgrade", Summary: "What an in-place upgrade to `?version=` would do (R-355, R-360): `possible`, and when not, `reasons`, each saying what to change; `image`, how Pando's deployment names its image, and `tag`, the moving tag the upgrade points at the new image; `breaking`, the versions in between that may break what works now, with their notes, which make `confirm_breaking` necessary; and `note`, that every app is unreachable while Pando restarts.", Verb: string(authz.InstallView)},
	{Method: "GET", Path: "/api/v1/upgrade/last", Group: "Installation", Title: "Get the last upgrade", Summary: "The most recent in-place upgrade, as `upgrade`, or null: `from`, `to`, `state` (`running`, `succeeded`, `rolled_back` or `failed`), `reason`, the new version's last log lines when it was rolled back, `backup_id` or `skip_backup`, and whether the rollback copy of the database is still kept (`snapshot_gone`, after 24 hours healthy).", Verb: string(authz.InstallView)},
	{Method: "POST", Path: "/api/v1/upgrade", Group: "Installation", Title: "Upgrade Pando", Summary: "Upgrade Pando in place (R-355 – R-360). Body: `version`; `passphrase` for the full backup taken first, or `skip_backup: true` to go without one, which is audited; and `confirm_breaking`, the version again, when the plan lists `breaking` versions. The image's signature is verified before anything else, and Pando refuses one that does not verify. Answers 202 with the upgrade: a helper then stops Pando, copies its database, starts the new version and waits for it to be ready, and puts the previous version and database back if it is not. Every app is unreachable while Pando restarts. `GET /upgrade/last` has the outcome once Pando is back.", Verb: string(authz.InstallUpgrade)},
	{Method: "GET", Path: "/api/v1/audit/archives/{archiveID}", Group: "Installation", Title: "Download an audit archive", Summary: "Download one archived month: gzipped JSON lines, one audit event per line with every field the live log held. `Repr-Digest` carries its SHA-256, the same as the manifest's `sha256`. Audited as `audit.archive.download` (R-388).", Verb: string(authz.InstallAuditRead)},
	{Method: "GET", Path: "/api/v1/backups", Group: "Installation", Title: "List backups", Summary: "The backups this installation holds, newest first, a page at a time: `limit` (default 100, at most 500) and `cursor` page; `next_cursor` continues; `app_id` narrows to one app. The first page also carries `attempts`: the most recent apps' last daily backup attempt, with why it was skipped or failed, at most a page of them.", Verb: string(authz.InstallBackupManage)},
	{Method: "POST", Path: "/api/v1/backups", Group: "Installation", Title: "Take a backup", Summary: "Take a backup now.", Verb: string(authz.InstallBackupManage)},
	{Method: "POST", Path: "/api/v1/backups/{backupID}/verify", Group: "Installation", Title: "Verify a backup", Summary: "Check a backup before it is needed, rather than at the moment of disaster (R-216).", Verb: string(authz.InstallBackupManage)},
	{Method: "POST", Path: "/api/v1/backups/{backupID}/restore", Group: "Installation", Title: "Restore from a backup", Summary: "Restore from a backup. Verified first: an incomplete one is refused rather than half-applied (R-215). Needs every installation permission, because a restore replaces every grant with the backup's (R-080a).", Verb: string(authz.InstallBackupManage)},

	// --- the reference itself --------------------------------------------
	{Method: "GET", Path: "/api/v1/reference", Group: "Reference", Title: "Get the API reference", Summary: "This document: every endpoint, every CLI command, every MCP tool and every error code, built from the running binary.", Public: true},
}

// handleReference serves the API's own description.
//
// It asks for nothing, not even a session. The document holds no data about
// this installation — no app, no account, no policy, nothing an anonymous
// visitor could not read in the repository, where `docs/api.md` is the same
// document. What it holds is the shape of the API, and R-261 makes that the
// product: a client that has to authenticate before it can learn how to
// authenticate is a product with one client.
//
// Nothing in it is a credential and nothing in it is a capability. The verbs it
// names are the ones every endpoint already returns in its own error envelope
// when a caller lacks them.
//
// Built once, the first time it is asked for: everything in it is fixed when
// the binary is, and it is the largest document the API serves.
func (s *Server) handleReference(w http.ResponseWriter, r *http.Request) {
	body, err := referenceJSON()
	if err != nil {
		Error(w, r, errs.Wrap(errs.Internal, "Pando could not assemble its API reference.", err))
		return
	}
	w.Header().Set("Content-Type", "application/json; charset=utf-8")
	w.WriteHeader(http.StatusOK)
	_, _ = w.Write(body)
}

// referenceJSON is the reference document, encoded as JSON writes it, built
// on first use and kept.
var referenceJSON = sync.OnceValues(func() ([]byte, error) {
	referenceBuilds.Add(1)
	var buf bytes.Buffer
	err := json.NewEncoder(&buf).Encode(reference.Build(routeDocs))
	return buf.Bytes(), err
})

// referenceBuilds counts how many times the reference was built, for the
// test that it is built once.
var referenceBuilds atomic.Int64

// Reference returns the assembled document, for the generator that writes
// `docs/` from it.
func Reference() reference.Document { return reference.Build(routeDocs) }

// normalizeRoutePath makes a chi pattern comparable with a documented path.
//
// chi reports a subrouter's index as "/api/v1/apps/" and a documented path says
// "/api/v1/apps", because that is what a person types.
func normalizeRoutePath(path string) string {
	if len(path) > 1 && strings.HasSuffix(path, "/") {
		return strings.TrimSuffix(path, "/")
	}
	return path
}
